/**
 * Behavior and accessibility checks for the importable Vue components shipped in scaffold/vue.
 * Run by scripts/test-vue-scaffold.mjs (`pnpm test:vue-scaffold`) against a project generated by the real CLI,
 * with tests/vue-scaffold/Demo.vue mounted. Uses the Vite dev server so Vue runtime warnings are visible.
 */
import { chromium } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

const URL = process.env.URL || 'http://127.0.0.1:5173/';
const results = [];
const logs = [];
let page;

function ok(name, cond, detail = '') {
  results.push({ name, pass: !!cond, detail });
}
async function test(name, fn) {
  try {
    await page.goto(URL);
    await page.waitForSelector('#demo-main');
    await page.emulateMedia({ reducedMotion: 'reduce' });
    await fn();
  } catch (e) {
    results.push({ name, pass: false, detail: String(e.message).split('\n')[0] });
  }
}
const active = () => page.evaluate(() => {
  const a = document.activeElement;
  return a ? (a.id || a.className || a.tagName) : null;
});

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, permissions: ['clipboard-read', 'clipboard-write'] });
page = await ctx.newPage();
page.setDefaultTimeout(5000);
page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) logs.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
await page.goto(URL);
await page.waitForSelector('#demo-main');
await page.emulateMedia({ reducedMotion: 'reduce' });

// ---------- Modal
await test('Modal: opens, focuses inside, Escape closes + restores focus', async () => {
  await page.click('#open-modal');
  await page.waitForSelector('[data-modal]:not([hidden])');
  ok('Modal opens (v-model:open true)', (await page.textContent('#modal-state')) === 'true');
  const inside = await page.evaluate(() => document.querySelector('[data-modal]').contains(document.activeElement));
  ok('Modal moves focus inside', inside);
  for (let i = 0; i < 5; i++) await page.keyboard.press('Tab');
  ok('Modal traps Tab', await page.evaluate(() => document.querySelector('[data-modal]').contains(document.activeElement)));
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-modal][hidden]', { state: 'attached' });
  ok('Modal Escape closes', (await page.textContent('#modal-state')) === 'false');
  ok('Modal restores focus to trigger', (await active()) === 'open-modal' || (await page.evaluate(() => document.activeElement?.id)) === 'open-modal');
});
await test('Modal: overlay click closes', async () => {
  await page.click('#open-modal');
  await page.waitForSelector('[data-modal]:not([hidden])');
  await page.mouse.click(20, 860);
  await page.waitForSelector('[data-modal][hidden]', { state: 'attached' });
  ok('Modal overlay click closes', (await page.textContent('#modal-state')) === 'false');
});

// ---------- AlertDialog / Sheet
for (const [name, openSel, rootSel] of [['AlertDialog', '#open-dialog', '[data-alert-dialog]'], ['Sheet', '#open-sheet', '[data-sheet]']]) {
  await test(`${name}: open, Escape closes, focus returns`, async () => {
    await page.click(openSel);
    await page.waitForSelector(`${rootSel}:not([hidden])`);
    ok(`${name} opens`, true);
    await page.keyboard.press('Escape');
    await page.waitForSelector(`${rootSel}[hidden]`, { state: 'attached' });
    ok(`${name} Escape closes`, true);
    await page.waitForTimeout(50);
    ok(`${name} restores focus to opener`, (await page.evaluate(() => document.activeElement?.id)) === openSel.slice(1));
  });
}

// ---------- Popover
await test('Popover: toggle, outside click, Escape', async () => {
  await page.click('[data-popover-trigger]');
  await page.waitForSelector('[data-popover-content]:not([hidden])');
  ok('Popover opens', true);
  await page.waitForTimeout(60);
  await page.mouse.click(20, 860);
  await page.waitForSelector('[data-popover-content][hidden]', { state: 'attached' });
  ok('Popover outside click closes', true);
  await page.click('[data-popover-trigger]');
  await page.waitForSelector('[data-popover-content]:not([hidden])');
  await page.waitForTimeout(60);
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-popover-content][hidden]', { state: 'attached' });
  ok('Popover Escape closes', true);
});

// ---------- HoverCard
await test('HoverCard: hover and keyboard focus', async () => {
  await page.hover('#hover-trigger');
  await page.waitForSelector('[data-hover-card-content]:not([hidden])', { timeout: 2000 });
  ok('HoverCard opens on hover', true);
  await page.mouse.move(5, 5);
  await page.waitForSelector('[data-hover-card-content][hidden]', { state: 'attached', timeout: 2000 });
  ok('HoverCard closes on leave', true);
  await page.focus('#hover-trigger');
  await page.waitForSelector('[data-hover-card-content]:not([hidden])', { timeout: 2000 });
  ok('HoverCard opens on keyboard focus', true);
  await page.evaluate(() => document.activeElement.blur());
});

// ---------- ContextMenu
await test('ContextMenu: right click opens at pointer, Escape closes', async () => {
  await page.click('#ctx-area', { button: 'right' });
  await page.waitForSelector('[data-context-menu-content]:not([hidden])');
  ok('ContextMenu opens', true);
  await page.waitForTimeout(100);
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-context-menu-content][hidden]', { state: 'attached' });
  ok('ContextMenu Escape closes', true);
});

// ---------- Tabs
await test('Tabs: click + arrow keys + change event', async () => {
  await page.click('#s-tabs [role=tab]:nth-child(2)');
  ok('Tabs click activates', (await page.getAttribute('#s-tabs [role=tab]:nth-child(2)', 'aria-selected')) === 'true');
  ok('Tabs shows panel two', await page.isVisible('#s-tabs [role=tabpanel][aria-hidden=false]'));
  await page.focus('#s-tabs [role=tab]:nth-child(2)');
  await page.keyboard.press('ArrowRight');
  ok('Tabs ArrowRight moves + activates', (await page.getAttribute('#s-tabs [role=tab]:nth-child(3)', 'aria-selected')) === 'true');
  ok('Tabs emits change', (await page.textContent('#tab-change')) === 'three');
  await page.keyboard.press('Home');
  ok('Tabs Home -> first', (await page.getAttribute('#s-tabs [role=tab]:nth-child(1)', 'aria-selected')) === 'true');
});

// ---------- Accordion
await test('Accordion: single-open + arrow navigation across items', async () => {
  const trig = (n) => `#s-accordion .accordion__item:nth-child(${n}) [data-accordion-trigger]`;
  ok('Accordion first item expanded by default', (await page.getAttribute(trig(1), 'aria-expanded')) === 'true');
  await page.click(trig(2));
  ok('Accordion opens second', (await page.getAttribute(trig(2), 'aria-expanded')) === 'true');
  ok('Accordion collapses first (single mode)', (await page.getAttribute(trig(1), 'aria-expanded')) === 'false');
  await page.focus(trig(2));
  await page.keyboard.press('ArrowDown');
  ok('Accordion ArrowDown focuses next trigger', await page.evaluate(() => document.activeElement?.id?.endsWith('trigger-c')));
  await page.keyboard.press('Enter');
  ok('Accordion Enter toggles focused item', (await page.getAttribute(trig(3), 'aria-expanded')) === 'true');
});

// ---------- Collapsible
await test('Collapsible toggles', async () => {
  const t = '#s-collapsible .collapsible__trigger';
  ok('Collapsible starts closed', !(await page.isVisible('#coll-body')));
  await page.click(t);
  ok('Collapsible opens', await page.isVisible('#coll-body'));
  ok('Collapsible aria-expanded', (await page.getAttribute(t, 'aria-expanded')) === 'true');
});

// ---------- Dropdown
await test('Dropdown: select, submenu, disabled, Escape', async () => {
  const trig = '#s-dropdown .dropdown__trigger';
  await page.click(trig);
  ok('Dropdown opens', (await page.getAttribute(trig, 'aria-expanded')) === 'true');
  await page.click('#s-dropdown .dropdown__item:has-text("Edit")');
  ok('Dropdown select event', (await page.textContent('#dd-selected')) === 'edit');
  ok('Dropdown closes after select', (await page.getAttribute(trig, 'aria-expanded')) === 'false');
  await page.click(trig);
  await page.locator('#s-dropdown .dropdown__item:has-text("Disabled")').waitFor({ state: 'visible' });
  await page.locator('#s-dropdown .dropdown__item:has-text("Disabled")').dispatchEvent('click');
  ok('Dropdown ignores disabled', (await page.textContent('#dd-selected')) === 'edit');
  await page.click('#s-dropdown .dropdown__item:has-text("More")');
  await page.locator('#s-dropdown .dropdown__submenu--open').waitFor({ state: 'visible' });
  ok('Dropdown submenu opens', true);
  await page.click('#s-dropdown .dropdown__submenu-item:has-text("Sub two")');
  ok('Dropdown submenu select', (await page.textContent('#dd-selected')) === 'sub2');
  await page.click(trig);
  await page.keyboard.press('Escape');
  ok('Dropdown Escape closes + focus trigger', (await page.getAttribute(trig, 'aria-expanded')) === 'false' && (await page.evaluate(() => document.activeElement?.classList.contains('dropdown__trigger'))));
  await page.focus(trig);
  await page.keyboard.press('ArrowDown');
  ok('Dropdown ArrowDown opens from trigger', (await page.getAttribute(trig, 'aria-expanded')) === 'true');
  await page.keyboard.press('Escape');
});

// ---------- Form controls
await test('Switch / Slider / Toggle v-model', async () => {
  await page.click('#s-form .switch');
  ok('Switch v-model', (await page.textContent('#sw-state')) === 'true');
  ok('Switch aria-checked', (await page.getAttribute('#s-form .switch__input', 'aria-checked')) === 'true');
  await page.fill('#s-form .slider__input', '70');
  ok('Slider v-model', (await page.textContent('#slider-state')) === '70');
  ok('Slider fill width', (await page.getAttribute('#s-form [data-slider-fill]', 'style')).includes('70%'));
  await page.click('#s-form .toggle >> nth=0');
  ok('Toggle v-model', (await page.textContent('#toggle-state')) === 'true');
  ok('Toggle aria-pressed', (await page.getAttribute('#s-form .toggle >> nth=0', 'aria-pressed')) === 'true');
});

// ---------- Feedback
await test('Alert dismiss + Toast auto-dismiss + ProgressBar', async () => {
  await page.click('#s-feedback .alert__close');
  ok('Alert dismiss event', (await page.textContent('#alert-dismissed')) === '1');
  ok('Alert removed', (await page.locator('#s-feedback .alert--success').count()) === 0);
  await page.waitForTimeout(600);
  ok('Toast auto-dismisses', (await page.locator('#s-feedback .toast').count()) === 1 && (await page.locator('#s-feedback .toast .alert').count()) === 0);
  ok('ProgressBar aria-valuenow', (await page.getAttribute('#s-feedback [role=progressbar] >> nth=0', 'aria-valuenow')) === '40');
  ok('ProgressBar label', (await page.textContent('#s-feedback .progress__label')) === '40%');
  ok('ProgressBar width style is a string (not [object Object])', (await page.getAttribute('#s-feedback .progress__bar >> nth=0', 'style')).includes('width: 40%'));
});

// ---------- Display
await test('Avatar / Breadcrumb / Pagination / Table', async () => {
  ok('Avatar initials from name', (await page.textContent('#s-display .avatar >> nth=0')).trim() === 'AL');
  ok('Breadcrumb current page', (await page.textContent('#s-display .breadcrumb__current')) === 'Page');
  ok('Pagination current', (await page.textContent('#s-display .pagination [aria-current=page]')).trim() === '3');
  ok('Pagination ellipsis', (await page.locator('#s-display .pagination__ellipsis').count()) >= 1);
  await page.click('#s-display .table__sort-trigger >> nth=1');
  const firstRow = async () => (await page.textContent('#s-display tbody tr:first-child td:first-child')).trim();
  ok('Table sorts ascending by number', (await firstRow()) === 'Apple');
  await page.click('#s-display .table__sort-trigger >> nth=1');
  ok('Table sorts descending', (await firstRow()) === 'Cherry');
  ok('Table aria-sort', (await page.getAttribute('#s-display th >> nth=1', 'aria-sort')) === 'descending');
  await page.fill('#s-display .table__filter', 'ban');
  ok('Table filter', (await page.locator('#s-display tbody tr').count()) === 1);
  await page.fill('#s-display .table__filter', '');
});

// ---------- CopyToClipboard
await test('CopyToClipboard copies and labels', async () => {
  const btn = '#s-misc .copy-to-clipboard >> nth=0';
  const label = await page.getAttribute(btn, 'aria-label');
  ok('CopyToClipboard label contains visible text (WCAG 2.5.3)', label.toLowerCase().includes('npm i rizzo-css'));
  await page.click(btn);
  ok('CopyToClipboard writes clipboard', (await page.evaluate(() => navigator.clipboard.readText())) === 'npm i rizzo-css');
  ok('CopyToClipboard feedback', (await page.textContent('#s-misc .copy-to-clipboard__feedback >> nth=0')) === 'Copied!');
  const l2 = await page.getAttribute('#s-misc .copy-to-clipboard >> nth=1', 'aria-label');
  ok('Icon-only label contains "Copy"', l2.toLowerCase().includes('copy'));
});

// ---------- ThemeSwitcher / FontSwitcher
await test('ThemeSwitcher: select theme + keyboard', async () => {
  const trig = '#theme-switcher-demo-trigger';
  ok('ThemeSwitcher accessible name has hidden prefix + visible label', ((await page.locator(trig).innerText()) + (await page.locator(trig + ' .sr-only').textContent())).includes('Select theme'));
  await page.click(trig);
  ok('ThemeSwitcher opens', (await page.getAttribute(trig, 'aria-expanded')) === 'true');
  await page.click('#theme-switcher-demo-menu [data-theme-value="github-light"]');
  ok('ThemeSwitcher applies data-theme', (await page.getAttribute('html', 'data-theme')) === 'github-light');
  ok('ThemeSwitcher persists to localStorage', (await page.evaluate(() => localStorage.getItem('theme'))) === 'github-light');
  ok('ThemeSwitcher label updates', (await page.textContent(trig + ' [data-theme-label]')).toLowerCase().includes('github light'));
  ok('ThemeSwitcher closes after select', (await page.getAttribute(trig, 'aria-expanded')) === 'false');
  await page.focus(trig);
  await page.keyboard.press('ArrowDown');
  await page.waitForFunction(() => document.activeElement?.classList.contains('theme-switcher__option'), null, { timeout: 2000 }).catch(() => {});
  ok('ThemeSwitcher ArrowDown opens + focuses option', (await page.getAttribute(trig, 'aria-expanded')) === 'true' && (await page.evaluate(() => document.activeElement?.classList.contains('theme-switcher__option'))));
  await page.keyboard.press('Escape');
  ok('ThemeSwitcher Escape closes + refocuses trigger', (await page.getAttribute(trig, 'aria-expanded')) === 'false' && (await page.evaluate((id) => document.activeElement?.id === id, 'theme-switcher-demo-trigger')));
  await page.click(trig);
  await page.click('#theme-switcher-demo-menu [data-theme-value="system"]');
  ok('ThemeSwitcher System option', (await page.textContent(trig + ' [data-theme-label]')).trim() === 'System');
});
await test('FontSwitcher: select pair', async () => {
  const trig = '#font-pair-trigger-demo';
  await page.click(trig);
  ok('FontSwitcher opens', (await page.getAttribute(trig, 'aria-expanded')) === 'true');
  await page.click('#font-pair-menu-demo [data-font-pair-value="inter-jetbrains"]');
  ok('FontSwitcher persists', (await page.evaluate(() => localStorage.getItem('fontPair'))) === 'inter-jetbrains');
  ok('FontSwitcher sets CSS var', (await page.evaluate(() => document.documentElement.style.getPropertyValue('--font-family'))).includes('inter'));
  await page.click(trig);
  await page.focus('#font-pair-menu-demo [data-font-pair-value="geist"]');
  await page.keyboard.press('Escape');
  ok('FontSwitcher Escape works from inside the menu', (await page.getAttribute(trig, 'aria-expanded')) === 'false');
});

// ---------- Search
await test('Search: Ctrl+K, focus input, Escape returns focus', async () => {
  await page.evaluate(() => document.activeElement?.blur());
  await page.keyboard.press('Control+k');
  await page.waitForSelector('[data-search-overlay][aria-hidden=false]');
  ok('Search opens on Ctrl+K', true);
  await page.waitForTimeout(50);
  ok('Search focuses input on open', await page.evaluate(() => document.activeElement?.classList.contains('search__input')));
  for (let i = 0; i < 6; i++) await page.keyboard.press('Tab');
  ok('Search traps Tab in panel', await page.evaluate(() => document.querySelector('.search__panel').contains(document.activeElement)));
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-search-overlay][aria-hidden=true]', { state: 'attached' });
  await page.waitForTimeout(50);
  ok('Search Escape closes + refocuses trigger', await page.evaluate(() => document.activeElement?.hasAttribute('data-search-trigger')));
  await page.keyboard.press('Control+k');
  await page.waitForSelector('[data-search-overlay][aria-hidden=false]');
  await page.keyboard.press('Control+k');
  await page.waitForSelector('[data-search-overlay][aria-hidden=true]', { state: 'attached' });
  ok('Search Ctrl+K toggles closed', true);
});

// ---------- Settings
await test('Settings: openSettings(), controls, Escape', async () => {
  // Uncontrolled <Settings /> opened from the Navbar's own button (a Boolean-prop-casting regression lived here).
  await page.click('.navbar__settings-btn');
  await page.waitForSelector('.settings__panel[data-open=true]');
  ok('Settings opens from the Navbar button (uncontrolled)', true);
  await page.fill('[data-font-size-slider]', '1.25');
  ok('Settings font size applies CSS var', (await page.evaluate(() => document.documentElement.style.getPropertyValue('--font-size-scale'))) === '1.25');
  ok('Settings font size label', (await page.textContent('.settings__label-value')) === '125%');
  await page.check('[data-reduced-motion]');
  ok('Settings reduced motion class', await page.evaluate(() => document.documentElement.classList.contains('reduced-motion')));
  await page.check('input[name=scrollbar-style][value=thick]');
  ok('Settings scrollbar style class', await page.evaluate(() => document.documentElement.classList.contains('scrollbar-thick')));
  ok('Settings persists', (await page.evaluate(() => localStorage.getItem('scrollbarStyle'))) === 'thick');
  ok('Settings embeds ThemeSwitcher', (await page.locator('#theme-switcher-settings-trigger').count()) === 1);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);
  ok('Settings Escape closes', (await page.locator('.settings__panel[data-open=true]').count()) === 0);
  await page.uncheck('[data-reduced-motion]').catch(() => {});
});

// ---------- Navbar mobile menu
await test('Navbar: mobile menu', async () => {
  await page.setViewportSize({ width: 420, height: 800 });
  await page.click('.navbar__toggle');
  ok('Navbar menu opens', await page.evaluate(() => document.querySelector('.navbar__menu').classList.contains('navbar__menu--open')));
  await page.keyboard.press('Escape');
  ok('Navbar Escape closes', !(await page.evaluate(() => document.querySelector('.navbar__menu').classList.contains('navbar__menu--open'))));
  await page.click('.navbar__toggle');
  await page.waitForTimeout(60);
  await page.mouse.click(5, 700);
  await page.waitForTimeout(50);
  ok('Navbar outside click closes', !(await page.evaluate(() => document.querySelector('.navbar__menu').classList.contains('navbar__menu--open'))));
  await page.setViewportSize({ width: 1280, height: 900 });
});

// ---------- BackToTop + Resizable
await test('BackToTop shows on scroll', async () => {
  ok('BackToTop hidden at top', (await page.getAttribute('[data-back-to-top]', 'data-visible')) === 'false');
  await page.evaluate(() => window.scrollTo(0, 2000));
  await page.waitForTimeout(100);
  ok('BackToTop visible after scroll', (await page.getAttribute('[data-back-to-top]', 'data-visible')) === 'true');
  await page.evaluate(() => window.scrollTo(0, 0));
});
await test('Resizable: drag handle resizes panes', async () => {
  await page.locator('#s-resize').scrollIntoViewIfNeeded();
  const before = await page.evaluate(() => document.getElementById('pane-a').parentElement.getBoundingClientRect().width);
  const box = await page.locator('[data-resizable-handle]').boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x - 150, box.y + box.height / 2, { steps: 5 });
  await page.mouse.up();
  const after = await page.evaluate(() => document.getElementById('pane-a').parentElement.getBoundingClientRect().width);
  ok('Resizable pane A shrinks on drag left', after < before - 50);
});

// ---------- Misc structure
await test('Static components render semantic markup', async () => {
  ok('Skeleton status role', (await page.getAttribute('#s-feedback .skeleton', 'role')) === 'status');
  ok('Separator role', (await page.getAttribute('#s-display .separator', 'role')) === 'separator');
  ok('Tooltip role', (await page.getAttribute('#s-display .tooltip', 'role')) === 'tooltip');
  ok('AspectRatio CSS var', (await page.getAttribute('#s-display .aspect-ratio', 'style')).includes('--aspect-ratio: 2'));
  ok('Empty slots', (await page.locator('#s-feedback .empty__action').count()) === 1);
  ok('ScrollArea viewport focusable', (await page.getAttribute('#s-display .scroll-area__viewport', 'tabindex')) === '0');
  ok('Dashboard main landmark + sidebar', (await page.locator('#s-dash .dashboard__sidebar').count()) === 1);
});

// ---------- axe
await test('axe: no critical/serious violations on the demo page', async () => {
  await page.evaluate(() => { localStorage.clear(); });
  await page.reload();
  await page.waitForSelector('#demo-main');
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const r = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa']).analyze();
  const bad = r.violations.filter((v) => ['critical', 'serious'].includes(v.impact));
  ok('axe critical/serious = 0', bad.length === 0, bad.map((v) => `${v.id} (${v.nodes.length}): ${v.nodes[0].html.slice(0, 80)}`).join(' | '));
});

await browser.close();

let pass = 0, fail = 0;
for (const r of results) {
  if (r.pass) pass++; else { fail++; console.log('FAIL', r.name, r.detail ? '-> ' + r.detail : ''); }
}
console.log(`\n${pass} passed, ${fail} failed`);
const vueWarn = logs.filter((l) => /Vue warn|pageerror|Uncaught|TypeError|ReferenceError/.test(l));
const other = logs.filter((l) => !vueWarn.includes(l));
console.log(`console: ${vueWarn.length} vue/page errors, ${other.length} other messages`);
vueWarn.slice(0, 15).forEach((l) => console.log('  ', l.slice(0, 260)));
other.slice(0, 5).forEach((l) => console.log('  (other)', l.slice(0, 200)));
process.exit(fail || vueWarn.length ? 1 : 0);
